</tool_PSNT><tool_result_Extk name="linux_ssh:linux_ssh_exec" status="success"><content>{"packageVersion":"0.1.0","success":true,"timeoutMs":10000,"exitCode":0,"timedOut":false,"output":"","sessionId":"","error":""}</content></tool_result_Extk>

