let code = fs.readFileSync(&apos;/root/kfmv4/src/client/modules/tree-render.ts&apos;, &apos;utf8&apos;);

// ====== 修改1：展开时 - 文字移到上方，和容器动画同步开始滑下 ======
const old1 = `      // 展开前隐藏直接子行，避免在展开过程中暴露
      container.children.forEach(c =&gt; { c.opacity = 0; });
      gsap.to(container, {
        height: fullHeight,
        duration: 0.05,
        ease: &apos;power2.out&apos;,
        onUpdate: function() {
          applyAnimOffsetSiblings(container, fullHeight, ancestors, root);
          renderer?.setRoot(renderer!.getRoot()!);
        },
        onComplete: () =&gt; {
          animLocked = false; animLockedAt = 0;
          slideInRows(container, root, tog);
        },
      });
      // 立即应用一帧偏移，避免 GSAP 首帧延迟导致闪烁
      applyAnimOffsetSiblings(container, fullHeight, ancestors, root);
      renderer?.setRoot(renderer!.getRoot()!);`;

const new1 = `      // 文字行移到容器上方，被 overflow:hidden 裁切；子容器隐藏
      container.children.forEach(c =&gt; {
        if (c.id?.startsWith(&apos;expanded-&apos;)) c.opacity = 0;
        else if (c.id?.startsWith(&apos;title-&apos;) || c.id?.startsWith(&apos;file-&apos;)) c.transform.translateY = -fullHeight;
      });
      renderer?.setRoot(renderer!.getRoot()!);

      // 容器高度动画 + 文字滑下动画同步开始
      gsap.to(container, {
        height: fullHeight,
        duration: 0.05,
        ease: &apos;power2.out&apos;,
        onUpdate: function() {
          applyAnimOffsetSiblings(container, fullHeight, ancestors, root);
          renderer?.setRoot(renderer!.getRoot()!);
        },
        onComplete: () =&gt; {
          animLocked = false; animLockedAt = 0;
          slideInRows(container, root, tog);
        },
      });

      // 文字从上方滑下（和容器动画同步）
      const textRows = container.children.filter(c =&gt;
        c.id?.startsWith(&apos;title-&apos;) || c.id?.startsWith(&apos;file-&apos;)
      );
      textRows.forEach(r =&gt; {
        gsap.to(r.transform, {
          translateY: 0,
          duration: 0.25,
          ease: &apos;power2.out&apos;,
          onUpdate: () =&gt; { renderer?.setRoot(renderer!.getRoot()!); },
        });
      });

      // 立即应用一帧偏移
      applyAnimOffsetSiblings(container, fullHeight, ancestors, root);
      renderer?.setRoot(renderer!.getRoot()!);`;

if (code.includes(old1)) { code = code.replace(old1, new1); console.log(&apos;Done 1&apos;); }
else { console.log(&apos;Pattern 1 not found&apos;); }

// ====== 修改2：slideInRows - 只处理子容器，不再处理文字动画 ======
const old2 = `  container.children.forEach(c =&gt; { c.opacity = 1; });
  rows.forEach(r =&gt; { r.transform.translateY = -totalH; });
  renderer?.setRoot(renderer!.getRoot()!);`;

const new2 = `  // 恢复子容器可见
  container.children.forEach(c =&gt; {
    if (c.id?.startsWith(&apos;expanded-&apos;)) c.opacity = 1;
  });
  renderer?.setRoot(renderer!.getRoot()!);`;

if (code.includes(old2)) { code = code.replace(old2, new2); console.log(&apos;Done 2&apos;); }
else { console.log(&apos;Pattern 2 not found&apos;); }

// ====== 修改3：子容器展开时只隐藏孙容器 ======
const old3 = &apos;    child.children.forEach(c =&gt; { c.opacity = 0; });&apos;;
const new3 = `    child.children.forEach(c =&gt; {
      if (c.id?.startsWith(&apos;expanded-&apos;)) c.opacity = 0;
    });`;
if (code.includes(old3)) { code = code.replace(old3, new3); console.log(&apos;Done 3&apos;); }
else { console.log(&apos;Pattern 3 not found&apos;); }

// ====== 修改4：文字链动画改为空（文字动画已在外层同步播放） ======
const old4 = `  // ====== 文字链：逐行滑入（不阻塞盒子链） ======
  rows.forEach((row, i) =&gt; {
    const rowDelay = (i * 25) / 1000;
    gsap.to(row.transform, {
      translateY: 0,
      duration: 0.2,
      ease: &apos;power2.out&apos;,
      delay: rowDelay,
      onUpdate: () =&gt; { renderer?.setRoot(renderer!.getRoot()!); },
    });
  });`;

const new4 = `  // 文字滑入动画已在外层（容器展开时）同步播放，此处不再处理`;

if (code.includes(old4)) { code = code.replace(old4, new4); console.log(&apos;Done 4&apos;); }
else { console.log(&apos;Pattern 4 not found&apos;); }

fs.writeFileSync(&apos;/root/kfmv4/src/client/modules/tree-render.ts&apos;, code);
&quot;, &quot;path&quot;: &quot;/tmp/fix_paper5.js&quot;}</param>
